const APP_BUILD = "fd7dcbb6d08e0";
// <<< PRECACHE-MANIFEST

/** This build's app cache. APP_BUILD is generated (see above). */
const APP_CACHE = 'space-cowboy-app-' + APP_BUILD;

// ---------------------------------------------------------------------------
// ROUTING PREDICATES
// ---------------------------------------------------------------------------

/** Should this URL be served cache-first? Mirrors CACHE_FIRST_PREFIXES in
 *  scripts/build-precache.mjs — the two lists must agree or the recorded
 *  CACHE_FIRST pair guards bytes this router never pins. */
function isCacheFirstURL(url) {
  if (url.pathname.includes('/vendor/')) return true;
  if (url.pathname.includes('/textures/')) return true;
  if (url.pathname.includes('/fonts/')) return true;
  return false;
}

/**
 * Curated JSON under ./data/ — small, and edited far more often than the code
 * that reads it. These ride the APP cache, not the asset cache: a data edit
 * ships with its build and lands with it (a city label added to
 * data/cities.json used to stay invisible while data/ was cache-first and
 * pinned until CACHE_NAME changed — Ipad.md §7). Used at install only: the
 * corner stamp is the one data file allowed to be absent.
 */
function isDataURL(url) {
  return url.pathname.includes('/data/');
}

/** data/build-tag.json — gitignored in a dev tree, written by build-tag.mjs,
 *  so a 404 at install is a skip, not a failure (UpdateWatch treats it as
 *  optional too). */
function isOptionalURL(url) {
  return isDataURL(url) && url.pathname.endsWith('/data/build-tag.json');
}

/** Synthetic offline response when both the local copy and the network fail. */
function offlineResponse(url) {
  return new Response(
    `// [SW] offline — ${url.href} not available\n`,
    {
      status: 503,
      statusText: 'Offline',
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
    }
  );
}

// ---------------------------------------------------------------------------
// INSTALL — fill this build's app cache in the background, all or nothing.
//
//   - app files (HTML, ./js/, ./data/, root files): ALWAYS refetched with
//     cache:'no-cache' (revalidates through GitHub Pages' 10-min cache and
//     Safari heuristics), so the new cache holds exactly the deployed bytes —
//     including files the page never requests at boot. ANY failure (except the
//     optional corner stamp) throws: the browser drops this worker and keeps
//     the old one, so a half-filled build can never become the one that starts
//     the game. The next update check retries.
//   - THEN each app file's bytes are checked (2026-10-13): sha1 of the response
//     against PRECACHE_HASHES[url]. Right after a deploy a CDN edge can still
//     hand out the OLD copy of one file (resp.ok, wrong bytes) — stored as is,
//     that file would sit beside the new ones until the next deploy. A mismatch
//     triggers ONE refetch with cache:'reload' and a cache-busting query
//     (?sc=<first 8 hex of the expected hash>; the query is what beats the
//     edge); the right bytes are stored under the ORIGINAL url key. Still wrong
//     → the file counts as failed like any fetch failure (the install is lost,
//     the old build stays). No entry for a url (a block from an older build),
//     no map, or no self.crypto.subtle → stored without a check. Never checked
//     whatever the map says: the corner stamp (data/build-tag.json) and the
//     asset class below.
//   - asset files (./vendor/, ./textures/, ./fonts/): skipped when already
//     stored. Immutable by contract; editing one requires a CACHE_NAME bump —
//     PINNED since 2026-09-05 (Session H tidy-up (5)): the generated block
//     records CACHE_FIRST = "<CACHE_NAME>:<content digest of the cache-first
//     set>", test-sw-precache recomputes the pair, and build-precache.mjs
//     refuses to regenerate a moved digest under an unbumped name
//     (cacheFirstGuard). This keeps the ~tens-of-MB texture set from being
//     re-downloaded on every deploy. A failed asset fetch is tolerated and
//     counted: the router fetches it on first use.
//   - NO skipWaiting() here (2026-10-12): the new build waits.
// ---------------------------------------------------------------------------
const PRECACHE_CONCURRENCY = 8;

/** Lowercase hex SHA-1 of a response body, or null when the bytes cannot be
 *  hashed here (no self.crypto.subtle, or the digest itself failed) — null
 *  means "unchecked", never "mismatch". Reads a clone: the caller stores the
 *  original. Always through `self.` — the test vm has no global `crypto`. */
async function sha1OfResponse(resp) {
  try {
    if (!(self.crypto && self.crypto.subtle)) return null;
    const digest = await self.crypto.subtle.digest('SHA-1', await resp.clone().arrayBuffer());
    return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('');
  } catch (_err) {
    return null;
  }
}

/** The expected sha1 of an app url, or null (no map / no entry → no check). */
function expectedHash(url) {
  if (typeof PRECACHE_HASHES === 'undefined' || !PRECACHE_HASHES) return null;
  return Object.prototype.hasOwnProperty.call(PRECACHE_HASHES, url) ? PRECACHE_HASHES[url] : null;
}

/**
 * Return the response to store for an APP url: `resp` when its bytes match
 * PRECACHE_HASHES (or nothing can be checked), else the cache-busted refetch
 * when THAT matches. Throws when the bytes are still wrong — the caller treats
 * it as a failed fetch. One console.warn per file whose first copy was wrong.
 */
async function checkedAppResponse(url, resp) {
  const want = expectedHash(url);
  if (!want) return resp;
  const got = await sha1OfResponse(resp);
  if (got === null || got === want) return resp;
  const retryUrl = url + (url.includes('?') ? '&' : '?') + 'sc=' + want.slice(0, 8);
  let again;
  try {
    again = await fetch(new Request(retryUrl, { cache: 'reload' }));
  } catch (err) {
    throw new Error('wrong bytes (sha1 ' + got + ', expected ' + want + ') and the refetch failed: ' + err);
  }
  if (!again || !again.ok) {
    throw new Error('wrong bytes (sha1 ' + got + ', expected ' + want + ') and the refetch gave HTTP ' + (again ? again.status : 'null'));
  }
  const second = await sha1OfResponse(again);
  if (second !== null && second !== want) {
    throw new Error('wrong bytes (sha1 ' + got + ', then ' + second + ' on the refetch; expected ' + want + ')');
  }
  // eslint-disable-next-line no-console
  console.warn('[SW] stale copy of', url, '(sha1 ' + got + ', expected ' + want + ') — refetched fresh with ?sc=');
  return again;
}

async function precacheAll() {
  const app = await caches.open(APP_CACHE);
  const assets = await caches.open(CACHE_NAME);
  const counts = { fetched: 0, present: 0, failed: 0, skipped: 0 };
  const lost = [];
  const queue = PRECACHE_URLS.slice();
  const worker = async () => {
    for (;;) {
      if (lost.length) return;   // an app file failed: the install is lost, spend no more bytes
      const url = queue.shift();
      if (url === undefined) return;
      let assetFile = false;
      try {
        const abs = new URL(url, self.location.href);
        assetFile = isCacheFirstURL(abs);
        if (assetFile && await assets.match(abs.href)) {
          counts.present += 1;
          continue;
        }
        const resp = await fetch(new Request(url, { cache: 'no-cache' }));
        if (!resp || !resp.ok) {
          if (!assetFile && isOptionalURL(abs) && resp && resp.status === 404) {
            counts.skipped += 1;
            continue;
          }
          throw new Error('HTTP ' + (resp ? resp.status : 'null'));
        }
        // App files only: the bytes must be the ones this build was made from.
        // The corner stamp is exempt even if a block ever listed it (re-timed at publish).
        const toStore = assetFile || isOptionalURL(abs) ? resp : await checkedAppResponse(url, resp);
        await (assetFile ? assets : app).put(url, toStore);
        counts.fetched += 1;
      } catch (err) {
        counts.failed += 1;
        if (!assetFile) lost.push(url);
        // eslint-disable-next-line no-console
        console.warn('[SW] pre-cache miss for', url, err);
      }
    }
  };
  await Promise.all(Array.from({ length: PRECACHE_CONCURRENCY }, worker));
  // The cache could have been deleted under us (an older build activating
  // mid-install); a build without its cache must not reach the waiting state.
  if (!lost.length && !(await caches.has(APP_CACHE))) lost.push('(the app cache vanished)');
  if (lost.length) {
    await caches.delete(APP_CACHE).catch(() => { /* nothing to clean */ });
    throw new Error(`[SW] install of ${APP_CACHE} failed — ${lost.length} app file(s) missing or wrong, first: ${lost[0]}`);
  }
  // REPORT — the install-burst count is the offline-permanence witness.
  // eslint-disable-next-line no-console
  console.info(
    `[SW] precache ${APP_CACHE} (build ${PRECACHE_BUILD}): ` +
    `${PRECACHE_URLS.length} entries — ${counts.fetched} fetched, ` +
    `${counts.present} already cached, ${counts.skipped} optional skipped, ${counts.failed} failed`
  );
}

self.addEventListener('install', (event) => {
  event.waitUntil(precacheAll());
});

// ---------------------------------------------------------------------------
// ACTIVATE — runs when no window uses the old worker (the next cold start) or
// after SKIP_WAITING. Keep this build's app cache and the asset cache, drop the
// rest, then take the open pages.
// ---------------------------------------------------------------------------
self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    try {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key !== APP_CACHE && key !== CACHE_NAME)
          .map((key) => caches.delete(key))
      );
      // The network-first era stored app files (js, data, index.html) in the
      // asset cache too; only the cache-first classes belong there.
      const assets = await caches.open(CACHE_NAME);
      await Promise.all(
        (await assets.keys())
          .filter((req) => !isCacheFirstURL(new URL(req.url)))
          .map((req) => assets.delete(req))
      );
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn('[SW] activate cleanup error:', err);
    }
    await self.clients.claim();
  })());
});

// ---------------------------------------------------------------------------
// MESSAGES — the update card talks to the WAITING worker.
//   {type:'SKIP_WAITING'}  switch now (the page reloads on controllerchange)
//   {type:'GET_BUILD'}     + a MessageChannel port: reply {appBuild, cache, windows}
//                          `windows` = how many window clients (controlled or
//                          not) this origin has open. The page switches by
//                          itself on the menu ONLY when it is 1: a switch
//                          deletes the old app cache, so a game running in a
//                          second tab would then load mixed modules. If the
//                          count cannot be had the field is left out (the page
//                          reads that as "not 1" and shows the card instead).
// ---------------------------------------------------------------------------
self.addEventListener('message', (event) => {
  const msg = event.data;
  if (!msg || typeof msg !== 'object') return;
  if (msg.type === 'SKIP_WAITING') {
    self.skipWaiting();
  } else if (msg.type === 'GET_BUILD') {
    const port = event.ports && event.ports[0];
    if (!port) return;
    const reply = (windows) => {
      const body = { appBuild: APP_BUILD, cache: APP_CACHE };
      if (typeof windows === 'number') body.windows = windows;
      try { port.postMessage(body); } catch (_err) { /* the page went away */ }
    };
    let counted;
    try {
      counted = Promise.resolve(self.clients.matchAll({ type: 'window', includeUncontrolled: true }))
        .then((list) => reply(list ? list.length : undefined), () => reply());
    } catch (_err) {
      counted = null;
      reply();
    }
    if (counted && typeof event.waitUntil === 'function') event.waitUntil(counted);
  }
});

// ---------------------------------------------------------------------------
// FETCH — route based on request URL.
// ---------------------------------------------------------------------------

/**
 * Look a request up in one cache: exact URL, then the BARE URL, then any match
 * ignoring the query. The bare step matters for version-stamped reads
 * (x.json?v=N, core/dataUrl.js) and `/?shot=1`-style navigations: they answer
 * from the precached entry, never from a stale stamped sibling —
 * cache.match(…, {ignoreSearch}) returns the OLDEST-inserted match, so it is
 * the last resort only. ignoreVary: a stored response's Vary header must never
 * turn a local hit into a miss.
 */
async function matchLocal(cache, request) {
  const exact = await cache.match(request, { ignoreVary: true });
  if (exact) return exact;
  const bareURL = new URL(request.url);
  bareURL.search = '';
  const bare = await cache.match(bareURL.href, { ignoreVary: true });
  if (bare) return bare;
  return (await cache.match(request, { ignoreSearch: true, ignoreVary: true })) || null;
}

/**
 * Local-first: answer from THIS build's app cache. A hit never touches the
 * network. A miss (a URL the manifest does not list) goes to the network with
 * no timeout, is not stored, and falls to the synthetic 503 if that fails.
 */
async function localFirst(request) {
  try {
    const cache = await caches.open(APP_CACHE);
    const hit = await matchLocal(cache, request);
    if (hit) return hit;
  } catch (_err) {
    // cache unreadable — fall through to the network
  }
  try {
    return await fetch(request);
  } catch (_err) {
    return offlineResponse(new URL(request.url));
  }
}

/**
 * Cache-first (asset cache): serve from cache if present, otherwise fetch from
 * the network and populate the cache on success. Only response.ok responses are
 * stored to avoid poisoning the cache. Clone BEFORE handing the response to the
 * page; `cache.put` consumes the clone's body.
 */
async function cacheFirst(request) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request, { ignoreVary: true });
  if (cached) return cached;

  try {
    const networkResponse = await fetch(request);
    if (networkResponse && networkResponse.ok) {
      const copy = networkResponse.clone();
      cache.put(request, copy).catch(() => { /* ignore */ });
    }
    return networkResponse;
  } catch (_err) {
    const fallback = await matchLocal(cache, request);
    return fallback || offlineResponse(new URL(request.url));
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Non-GET requests bypass the SW entirely.
  if (request.method !== 'GET') return;

  let url;
  try {
    url = new URL(request.url);
  } catch (_err) {
    return; // malformed URL — let the browser handle it.
  }

  // Don't intercept the SW's own URL (the browser's update check must reach the wire).
  if (url.pathname.endsWith('/sw.js')) return;

  // Only handle http(s) — skip chrome-extension://, data:, blob:, etc. — and
  // only our own origin.
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return;
  if (url.origin !== self.location.origin) return;

  // Cache-first: vendored Three.js (./vendor/), textures and the B612 fonts
  // (./fonts/) — immutable blobs.
  if (isCacheFirstURL(url)) {
    event.respondWith(cacheFirst(request));
    return;
  }

  // Everything else — HTML navigations, game .js, data/ JSON, manifest, icons —
  // starts from the local copy of THIS build. Never network-first.
  event.respondWith(localFirst(request));
});
